// priority: 7550
// Gregtech Grindless - EMI information pages of the LuV era multiblocks (kubejs/assets/emi/recipe/additions/grindless/<id>.json, type emi:info).
// One page per controller: what it does, what it is for, what it needs. Their recipes show in EMI under the controller itself.
// Tooltips live in the luv_*_lang.js files; every key is in en_us and es_es.
ClientEvents.lang('en_us', event => {
    var add = function (key, value) { event.add('grindless', key, value) }

    add('emi.grindless.info.harpoon_anchor_drill.0', "The Harpoon Anchor Drill is the vein drill of the asteroid belt. Put the M-, S- or C-type vein sample and an HSS-S drill bit in the input bus; it gives 11.25 raw ores a run and wears the bit and an anchor harpoon.")
    add('emi.grindless.info.harpoon_anchor_drill.1', "It works only in the belt and runs only its own recipes. No fluid: it is vacuum. Up to 256 runs at once, as the energy hatches allow.")
    add('emi.grindless.info.harpoon_anchor_drill.2', "Vein drill family, step 7a: the asteroid belt only. A drill pushes itself off the rock where there is almost no gravity, so harpoons hold it down. It runs only its own recipes: the belt's M-, S- and C-type veins.")
    add('emi.grindless.info.harpoon_anchor_drill.3', "11.25 raw ores and a tuff a run. Wear: the HSS-S drill bit at 0.25% a run and an anchor harpoon at 1%. No fluid: it is vacuum. Up to 256 runs at once, as the energy hatches allow.")
    add('emi.grindless.info.harpoon_anchor_drill.4', "A 7x8x7 spider: a 5x6 pad of asteroid regolith casing, four HSS-S harpoon legs, a 3x3x3 body with a Whipple shield on its back, and a titanium derrick over a tungstensteel drill string. Body: 1-2 energy hatches, 1-2 input buses, 1-2 output buses.")

    add('emi.grindless.info.asteroid_processor.0', "The Asteroid Processor runs the Mond process. Circuit 1: crushed meteoric iron. Circuit 3: meteoric iron dust. Both give iron, nickel and cobalt and leave the asteroid PGM concentrate. Circuit 2: splits crushed tetrataenite from its kamacite.")
    add('emi.grindless.info.asteroid_processor.1', "Circuits 1 and 3 need a 1,000 mB carbon monoxide charge in an input hatch, never used up. It keeps the concentrate and refuses item voiding. Works anywhere.")
    add('emi.grindless.info.asteroid_processor.2', "The Mond process: metal and carbon monoxide make gaseous carbonyls that are distilled apart and broken down into pure iron, nickel and cobalt. Platinum metals form no carbonyl and stay behind as the asteroid PGM concentrate, which only this machine makes.")
    add('emi.grindless.info.asteroid_processor.3', "Circuit 1: 16 crushed meteoric iron. Circuit 3: 16 meteoric iron dust. Both need a 1,000 mB carbon monoxide charge in an input hatch, never used up, and keep the concentrate: no item voiding. Circuit 2: the magnetic split of crushed tetrataenite from its kamacite.")
    add('emi.grindless.info.asteroid_processor.4', "A hollow 5x5x6 carbonyl column of steel pipe casing, a 3x3x3 magnetic separator of steel casing and a laminated glass CO gas holder. Separator: 1-2 energy hatches, input/output buses and input hatches. Works anywhere.")

    add('emi.grindless.info.optical_miner.0', "The Optical Miner works only in the asteroid belt. Circuit 1 bags a C-type boulder and spalls it with sunlight: water, carbon dioxide, carbon and the chondritic extract. Circuit 2 turns carbon dioxide and carbon into carbon monoxide.")
    add('emi.grindless.info.optical_miner.1', "Circuit 1 starts only by day, with the sun on the receiver and all eight mirrors under open sky. Circuit 2 needs no sun. It keeps everything and refuses voiding. The carbon monoxide feeds the Asteroid Processor.")
    add('emi.grindless.info.optical_miner.2', "The asteroid belt only. Circuit 1 bags a C-type boulder and spalls it with concentrated sunlight: water, carbon dioxide, carbon and the chondritic extract, which only this machine makes. A capture bag is used up at 5% a run.")
    add('emi.grindless.info.optical_miner.3', "A circuit 1 run starts only by day with the sun on the receiver window and all eight mirrors under open sky. Circuit 2 (Boudouard) turns carbon dioxide and carbon into the asteroid processor's carbon monoxide, sun or not. It keeps everything it makes: no voiding.")
    add('emi.grindless.info.optical_miner.4', "Eight heliostat mirrors (laminated glass on titanium posts) round a 3x3x3 robust capture chamber with a laminated glass receiver, a frostproof cold trap and a 3x3x3 hut of asteroid regolith casing. Hut: 1-2 energy hatches, 1 input bus, output buses, up to 1 input hatch and 1-3 output hatches.")

    add('emi.grindless.info.biofoundry.0', "The Biofoundry is GregTech's sterile chain in one hall, with no sterile cleanroom. Circuits 1-2: collagen. 3: gelatin. 4: agar. 5: bacterial sludge. 6: mutagen. 7: sterile growth medium. 8: stem cells.")
    add('emi.grindless.info.biofoundry.1', "Everything goes in and out through the back wall. It refuses voiding: sludge, acid and phosphorus go back into the chain. Its products feed the Organoid Lab.")
    add('emi.grindless.info.biofoundry.2', "A sealed sterile hall: plascrete and cleanroom glass, four fermenter columns, an autoclave bay, a ceiling of UV lamps and an iron-door airlock. Everything goes in and out through the back wall. The programmed circuit picks the step.")
    add('emi.grindless.info.biofoundry.3', "GregTech's whole sterile chain at LuV, with no sterile cleanroom: 1-2 collagen (bone or bone meal), 3 gelatin, 4 agar, 5 bacterial sludge, 6 mutagen, 7 sterile growth medium, 8 stem cells. Same ratios and same energy as GregTech's own steps; merged steps keep their intermediates inside.")
    add('emi.grindless.info.biofoundry.4', "9 and 10: engineered barley and tobacco seeds for the rotating hydroponic ring, with the bacteria as the vector that carries the gene. The bacteria come from Europa's culture.")
    add('emi.grindless.info.biofoundry.5', "It keeps all it makes: the stem cells' sludge goes back to mutagen, the diluted acid and the phosphorus back to acid, and it refuses voiding. Back wall: 1-2 energy hatches, 1-4 input buses, 1-2 output buses, 1-3 input hatches and 1-2 output hatches. ME parts fit.")

    add('emi.grindless.info.coated_conductor_line.0', "The Coated Conductor Line makes second-generation superconducting tape. Circuit 1: nickel-tungsten tape from nickel and tungsten dust. Circuit 2: ITBTC coated conductor from that tape, ITBTC dust, oxygen and molten silver.")
    add('emi.grindless.info.coated_conductor_line.1', "It needs no 6,000 K blast furnace and no liquid helium. The coated conductor goes to the HTS Magnet Works.")
    add('emi.grindless.info.coated_conductor_line.2', "A reel-to-reel line for second-generation superconducting tape: payoff reel, rolling stand, annealing furnace, laser deposition chamber, oxygen anneal tube, silver sputter cell and take-up reel. The programmed circuit picks the step: 1 substrate, 2 tape.")
    add('emi.grindless.info.coated_conductor_line.3', "Substrate: 19 nickel dust and 1 tungsten dust give 20 nickel-tungsten tape. Tape: 16 of it, 1 ITBTC dust, 1,000 mB of oxygen and 36 mB of molten silver give 16 ITBTC coated conductor, with no 6,000 K blast furnace and no liquid helium.")
    add('emi.grindless.info.coated_conductor_line.4', "The bed's front and back rows take 1-2 energy hatches, 1-3 input buses, 1-2 input hatches and 1-2 output buses; ME parts fit. The coated conductor feeds the HTS magnet works.")

    add('emi.grindless.info.algae_bioreactor.0', "The Algae Bioreactor grows living matter. Circuit 1, anywhere: algae turn water and CO2 into biomass and oxygen. Circuit 2, Europa only: Europan brine, hydrogen peroxide, hydrogen and chondritic extract make bacteria, seeded by the ocean sample.")
    add('emi.grindless.info.algae_bioreactor.1', "The ocean sample is kept. It is the only source of bacteria in the pack and refuses voiding.")
    add('emi.grindless.info.algae_bioreactor.2', "Greenhouse family, step 5. Circuit 1, anywhere: algae under LED lamps turn water and CO2 into biomass and oxygen. Circuit 2, Europa only: brine, hydrogen peroxide, hydrogen and the belt's chondritic extract feed the Europan culture, seeded by the ocean sample (kept): the only bacteria.")
    add('emi.grindless.info.algae_bioreactor.3', "Three 1x1x10 laminated glass tubes with GT lamps between them, on a 5x5x3 sealed sulfur concrete base with a radiation vault roof. Base: 1-2 energy hatches, input buses, 1-3 input hatches and 1-2 output hatches.")
    add('emi.grindless.info.algae_bioreactor.4', "The bacteria go home to the biofoundry. Keeps everything it makes: no voiding.")

    add('emi.grindless.info.cryobot.0', "The Cryobot is the vein drill of Europa. Circuit 1: a cryobot probe melts down to the ocean and brings back the ocean sample and 1,000 mB of brine. Circuit 2: 8,000 mB of Europan brine and 2,000 mB of water a run.")
    add('emi.grindless.info.cryobot.1', "It works only on Europa and runs only its own recipes. The melt head wears 0.25% a run and the RTG pellet lasts about an hour. It refuses voiding.")
    add('emi.grindless.info.cryobot.2', "Vein drill family, step 7b. Europa only. Circuit 1: a cryobot probe melts down to the ocean and brings back the Europan ocean sample and 1,000 mB of brine. Circuit 2: 8,000 mB of Europan brine and 2,000 mB of meltwater a run.")
    add('emi.grindless.info.cryobot.3', "The melt head wears 0.25% a brine run and its RTG pellet is used up about once an hour. Runs only its own recipes. Keeps the sample and the brine: no voiding.")
    add('emi.grindless.info.cryobot.4', "5x5 base of sulfur concrete around a radiation-vault core, a 3x3x10 tungsten steel derrick under a vault head with a tungstensteel gearbox drum, and a 1x5 shaft of packed or blue ice under the middle of the base. Base: 1-2 energy hatches, input and output buses, 1-2 output hatches.")

    add('emi.grindless.info.gravitational_wave_detector.0', "The Gravitational-Wave Detector works only on Ganymede. Circuit 1: a data orb, 100 mB of liquid helium and the Sagittarius A* Signal (kept) give a Gravitational-Wave Catalogue after a 12,000-tick run.")
    add('emi.grindless.info.gravitational_wave_detector.1', "Keep the whole L loaded while it listens. It keeps its catalogues and refuses item voiding.")
    add('emi.grindless.info.gravitational_wave_detector.2', "Ganymede only: quiet ice, 110 K and its own magnetosphere. Circuit 1: a data orb, 100 mB Liquid Helium and the Sagittarius A* Signal (kept) give a Gravitational-Wave Catalogue after a 12,000-tick observing run. Keep the whole L loaded while it listens.")
    add('emi.grindless.info.gravitational_wave_detector.3', "A buried L, 33x5x33: a 5x5x5 frostproof vertex (controller, hatches, maintenance), two hollow 3x3 clean stainless steel tubes 25 long, a 3x3x3 frostproof end station on each arm, four sapphire test masses (two in the vertex walls, one facing the vertex at each end) and packed or blue ice over every tube and end station. Keeps its catalogues: no voiding.")

    add('emi.grindless.info.coilgun_launcher.0', "The Coilgun Probe Launcher works only on Ganymede. Circuit 1 fires a Jupiter entry probe for the Jovian Atmosphere Survey. Circuit 2 sends a Saturn flyby probe on a Jupiter slingshot for the Saturn Transfer Chart.")
    add('emi.grindless.info.coilgun_launcher.1', "No air and 110 K: the coils superconduct with no cryostat. It keeps the probes' data and refuses item voiding.")
    add('emi.grindless.info.coilgun_launcher.2', "Ganymede only: no air, and at 110 K the Hg-1223 coils superconduct with no cryostat. Circuit 1 fires a Jupiter entry probe for the Jovian Atmosphere Survey; circuit 2 sends a Saturn flyby probe on a Jupiter slingshot for the Saturn Transfer Chart.")
    add('emi.grindless.info.coilgun_launcher.3', "37x5x8: a barrel of 33 rings of eight coilgun coil casings around an open bore, a 5x5x4 robust tungstensteel breech (controller on the rear face, loading bus, hatches, maintenance) and a 3x3x3 tungstensteel pulse bank beside it. Keeps its data: no voiding.")

    add('emi.grindless.info.helium_refrigerator.0', "The Helium Refrigerator is a closed-loop helium cooler. It does the vacuum freezer's job on hot ingots and on molten metal in an ingot mold, but spends 25 mB of liquid helium a run instead of 250 mB.")
    add('emi.grindless.info.helium_refrigerator.1', "It pays the difference in EU to liquefy the helium again. 50 mB of liquid nitrogen precools the loop and leaves as nitrogen gas.")
    add('emi.grindless.info.helium_refrigerator.2', "A Claude-cycle helium refrigerator: a cold box with two turbo-expanders, a compressor house and a helium gas holder. It cools every hot ingot, and every molten metal in an ingot mold, that the vacuum freezer cools with liquid helium.")
    add('emi.grindless.info.helium_refrigerator.3', "The helium runs in a closed loop: a run spends 25 mB of liquid helium instead of the freezer's 250 mB, and pays in EU to liquefy the rest again. 50 mB of liquid nitrogen precools the loop and leaves as nitrogen gas.")
    add('emi.grindless.info.helium_refrigerator.4', "It needs a 4,000 mB liquid helium charge in its input hatches on top of the make-up. The charge is never used up; with a parallel hatch it is still 4,000 mB, plus 25 mB for each copy.")
    add('emi.grindless.info.helium_refrigerator.5', "The cold box's floor ring takes 1-2 energy hatches, 1-2 input buses, 1-2 output buses, 1-4 input hatches and 1-2 output hatches; ME parts fit. The nitrogen goes back to the cryogenic plant, or is voided.")

    add('emi.grindless.info.hts_magnet_works.0', "The HTS Magnet Works makes magnets from superconducting tape. Circuit 1: HTS coil (superconducting coil block). 2: LuV SMES cell. 3: coilgun coil casings. 4: magnetic bearing.")
    add('emi.grindless.info.hts_magnet_works.1', "The HTS coil takes ITBTC coated conductor, niobium-titanium foils, trinium and epoxy, with far less trinium than GTM's LuV recipe. The SMES cell is the wireless network's LuV cell.")
    add('emi.grindless.info.hts_magnet_works.2', "A magnet factory: superconducting tape is wound on a turning mandrel, impregnated with epoxy in a vacuum tank and cold-tested in a liquid-helium cryostat. The programmed circuit picks the product: 1 HTS coil, 2 LuV SMES cell, 3 coilgun coil casings, 4 magnetic bearing.")
    add('emi.grindless.info.hts_magnet_works.3', "HTS coil: 16 ITBTC coated conductor, 16 niobium-titanium foils, 144 mB of trinium and 144 mB of epoxy make GTM's superconducting coil block with a twenty-fourth of the trinium its LuV recipe takes. SMES cell: the wireless network's LuV cell, 983,040,000 EU in a coil's field.")
    add('emi.grindless.info.hts_magnet_works.4', "Every winding needs a 1,000 mB liquid helium charge in an input hatch for its cold test: it is never used up. Nothing is left over.")
    add('emi.grindless.info.hts_magnet_works.5', "The base's front and back rows and the cryostat's front wall take 1-2 energy hatches, 1-3 input buses, 1-3 input hatches and 1-2 output buses; ME parts fit. Two energy hatches of one tier lift the voltage one tier, wireless ones included.")

    add('emi.grindless.info.flux_tube_tether.0', "The Flux-Tube Tether is a power plant in Io orbit only. A bare tether sweeps Io's plasma torus and burns nothing. Each 20 s run needs circuit 1, 50 mB of argon and two tether spools in the bus.")
    add('emi.grindless.info.flux_tube_tether.1', "It makes 65,536 EU/t per reel cell: 131,072 EU/t with both. A spool wears out about once an hour.")
    add('emi.grindless.info.flux_tube_tether.2', "Jupiter's spin as power: a bare tether paid out from a station into Io's plasma torus, which sweeps past it at about 57 km/s and drives a current through it. It burns nothing. Only in Io orbit.")
    add('emi.grindless.info.flux_tube_tether.3', "Each 20 s run needs circuit 1, 50 mB of argon (the hollow cathode, 25 mB per reel) and two tether spools in the bus, and makes 65,536 EU/t per reel cell: 131,072 EU/t with both. A spool wears out about once an hour.")
    add('emi.grindless.info.flux_tube_tether.4', "Its EU leaves through 1-4 dynamo hatches, or a LuV wireless dynamo hatch into the network; both reels need 131,072 EU/t of room (a 4 A LuV hatch).")
    add('emi.grindless.info.flux_tube_tether.5', "5x15x5: a 5x5x5 deployer with station truss casing edges and radiation vault casing faces (1-4 dynamo hatches, 1 input bus), two reels of three tungstensteel gearboxes inside, an input hatch (the hollow-cathode port) on the roof beside the tether, and a tether of aluminium frames from the roof's centre 10 blocks up.")

    add('emi.grindless.info.fumarole_condenser.0', "The Fumarole Condenser works Io's volcanic gases. Circuit 1, only on Io: SO2, sulfur and an Ionian sublimate. Circuit 2, anywhere: sublimates, hydrogen and an HCl charge give germanium and indium. Circuit 3, only on Io: sulfur concrete.")
    add('emi.grindless.info.fumarole_condenser.1', "The HCl charge is kept. It refuses voiding. It is the only source of germanium before ZPM.")
    add('emi.grindless.info.fumarole_condenser.2', "Io's volcanic gases, cooled in bands: the only germanium before ZPM, Io's indium and sulfur concrete. Its housing is radiation vault casing.")
    add('emi.grindless.info.fumarole_condenser.3', "Circuit 1, only on Io: collect 4,000 mB SO2, 8 sulfur and an Ionian sublimate. Circuit 2, anywhere: 4 sublimates + 2,000 mB hydrogen over a 1,000 mB HCl charge (kept) -> 2 germanium, 1 indium and water. Circuit 3, only on Io: 8 sulfur + 8 basalt or black sand -> 8 sulfur concrete.")
    add('emi.grindless.info.fumarole_condenser.4', "It keeps everything it makes: it refuses to run while set to void. Takes the parallel hatch. Runs on a brought IV wireless energy hatch.")
    add('emi.grindless.info.fumarole_condenser.5', "5x15x5: three Biomes O' Plenty brimstone fumaroles in the floor under the column; a 5x5x2 vault housing (1-2 energy hatches, 1-2 input and output buses, 1-3 input hatches, 1-2 output hatches, an optional parallel hatch); a 3x3 column of four 3-block zones: robust tungstensteel, clean stainless steel, aluminium frames, frostproof casing.")

    add('emi.grindless.info.volcanic_intake.0', "The Volcanic Intake is a power plant on Io only. It burns nothing: a sulfur dioxide loop runs between the patera's magma and Io's cold sky. Each 20 s run needs circuit 1 and a 4,000 mB SO2 charge, kept.")
    add('emi.grindless.info.volcanic_intake.1', "It makes 32,768 EU/t per complete turbine module, up to 131,072 EU/t. A heat exchanger bundle per module wears out about once an hour.")
    add('emi.grindless.info.volcanic_intake.2', "Io's tidal heat as power: a closed Rankine loop of sulfur dioxide between the patera's magma and Io's 110 K sky. It burns nothing. Only on Io.")
    add('emi.grindless.info.volcanic_intake.3', "Each 20 s run needs circuit 1 and a 4,000 mB SO2 charge (kept) and makes 32,768 EU/t per complete turbine module, up to 131,072 EU/t. A heat exchanger bundle per module wears out about once an hour.")
    add('emi.grindless.info.volcanic_intake.4', "Its EU leaves through 1-4 dynamo hatches, or a LuV wireless dynamo hatch into the network. Up to 3 more turbine modules: each slot is a whole 3x3x3 module of titanium turbine casing, or air.")
    add('emi.grindless.info.volcanic_intake.5', "11x12x5: a 5x5 sulfur concrete footing with a 3x3 of magma blocks under a tungstensteel firebox hot plate; a vault room (1 input bus, 1 input hatch, dynamo hatches) and a 5x5x10 sulfur concrete tower round a tungstensteel pipe riser; night-sky radiator fins on top; turbine modules on both sides.")

    add('emi.grindless.info.mega_chemical_complex.0', "The Mega Chemical Complex has two modes picked in the controller: every chemical reactor and large chemical reactor recipe, or the long PTFE, epoxy and para-aramid lines in one step with every byproduct as an output.")
    add('emi.grindless.info.mega_chemical_complex.1', "Parallels are 2^(coil temperature / 900 K) times the parallel hatch. Each copy pays full EU/t, so the energy hatches set how many run. Coils above Cupronickel cut the energy by 5%, down to 80%.")
    add('emi.grindless.info.mega_chemical_complex.2', "The massive large chemical reactor, with two modes picked in the controller: every large chemical reactor and chemical reactor recipe, or its own long chemical lines (PTFE, epoxy, para-aramid) made in one step from the live recipes: the same inputs, every byproduct as an output, and the energy of all the stages added up.")
    add('emi.grindless.info.mega_chemical_complex.3', "Copies at once: 2^(coil temperature / 900 K) times the parallel hatch, with no cap (HSS-G coil 64 x LuV hatch 16 = 1024; Naquadah coil 256 x ZPM hatch 64 = 16384). Each copy pays its full EU/t, so the energy hatches set how many run: floor(hatch voltage / recipe EU/t).")
    add('emi.grindless.info.mega_chemical_complex.4', "Every coil step above Cupronickel cuts the energy by 5% (down to 80%), spare voltage gives perfect overclocks, and batch mode is on.")
    add('emi.grindless.info.mega_chemical_complex.5', "Needs, in a 15 x 15 x 15 shell of PTFE inert casings with HSS-S frames on the edges: 4 rings of 32 heating coils of one type, a column of PTFE pipe casings, laminated glass in the side walls; in any casing cell 1 maintenance hatch, 1 or 2 energy hatches, 1 parallel hatch, up to 2 input and 2 output buses, up to 8 fluid input and 6 fluid output hatches.")

    add('emi.grindless.info.hydroponic_ring.0', "The Rotating Hydroponic Ring is orbit-only molecular farming, not a crop multiplier. Circuit 5: kept barley seed, water and CO2 give neurotrophic factor. Circuit 6: kept tobacco seed gives plant collagen. Both also make biomass and oxygen.")
    add('emi.grindless.info.hydroponic_ring.1', "Biomass feeds the Biofoundry and the neurotrophic factor feeds the Organoid Lab. Oxygen supports the station. It refuses voiding.")
    add('emi.grindless.info.hydroponic_ring.2', "Orbit-only molecular farming, not a crop multiplier. Circuit 5: kept barley seed, water and CO2 to neurotrophic factor. Circuit 6: kept tobacco seed to plant collagen. Both also make biomass and oxygen.")
    add('emi.grindless.info.hydroponic_ring.3', "15x15x3 annular soil bed under tempered glass; titanium spokes join a 3x3x3 hub with four magnetic bearings. Docking controller on the near rim. Hub: 1-2 energy hatches, input/output buses, 1-2 input hatches and 2 output hatches. Biomass feeds the biofoundry; oxygen supports the station. No ordinary crop mode; no voiding.")

    add('emi.grindless.info.organoid_lab.0', "The Organoid Lab works in orbit only, with a cleanroom or a cleaning maintenance hatch. Circuit 1 grows a neural organoid from stem cells, sterile medium and neurotrophic factor. Circuit 2 assembles a neuro processing unit.")
    add('emi.grindless.info.organoid_lab.1', "The processing unit takes 30,720 EU/t for 1,563 ticks. Stem cells come from the Biofoundry, neurotrophic factor from the Hydroponic Ring. It keeps all products and refuses voiding.")
    add('emi.grindless.info.organoid_lab.2', "Orbit only, with a cleanroom or cleaning maintenance hatch. Circuit 1 grows a neural organoid from stem cells, sterile medium and the ring's neurotrophic factor. Circuit 2 assembles a neuro processing unit at 30,720 EU/t for 1,563 ticks.")
    add('emi.grindless.info.organoid_lab.3', "5x5x5 sealed plascrete/cleanroom-glass module, laminated incubator, four filter casings and a maintenance cell, docked to station truss. 1-2 energy hatches, input/output buses and input hatches. Keeps all products: no voiding.")

    add('emi.grindless.info.zero_g_crystal_grower.0', "The Zero-G Crystal Grower works in orbit only, with a cleanroom or a cleaning maintenance hatch. Circuits 1-5 grow raw crystal chips with 100% certainty in 3,000 ticks, at GregTech's dopant doses. Circuit 6 grows a sapphire test mass.")
    add('emi.grindless.info.zero_g_crystal_grower.1', "The sapphire test mass is a part of the gravitational-wave detector.")
    add('emi.grindless.info.zero_g_crystal_grower.2', "Orbit only. Circuits 1-5 grow raw crystal chips with 100% certainty in 3,000 ticks, at GregTech's original dopant doses. Circuit 6 grows a sapphire test mass.")
    add('emi.grindless.info.zero_g_crystal_grower.3', "5x5x5 station module; inert 3x3x3 growth core and laminated ports. Requires a cleanroom or cleaning maintenance hatch in its maintenance cell. 1-2 energy hatches, input/output buses and input hatches.")

    add('emi.grindless.info.microgravity_smelter.0', "The Microgravity Smelter works in any orbit. Circuit 1: ZBLAN optical pipes. Circuit 2: Whipple shield foam. Circuit 3: cold naquadah alloy with no helium.")
    add('emi.grindless.info.microgravity_smelter.1', "Blend the ZBLAN in the Large Mixing Vessel. Optical pipes cannot be recycled and need a cleaning maintenance hatch. It takes an optional parallel hatch.")
    add('emi.grindless.info.microgravity_smelter.2', "Any orbit. A 3x3x7 station module, eight HSS-G coils around an empty levitation centre, and a six-block fibre drawing tower.")
    add('emi.grindless.info.microgravity_smelter.3', "Circuits 1/2/3: ZBLAN optical pipes / Whipple shield foam / cold naquadah alloy without helium. Blend ZBLAN in the Large Mixing Vessel (73,250 mB fluorine per 25 dust). Optical pipes cannot be recycled.")
    add('emi.grindless.info.microgravity_smelter.4', "1-2 energy hatches, 1-2 input buses, 1-2 output buses, 1-2 fluid inputs; optional parallel hatch. One maintenance cell: use a cleaning maintenance hatch for optical pipes.")

    add('emi.grindless.info.wake_shield_facility.0', "The Wake Shield Facility works in any orbit and always needs a cleanroom or a cleaning maintenance hatch. Circuit 1: UHPIC wafer. Circuit 2: HPIC wafer. Circuit 3: triple-junction wafer.")
    add('emi.grindless.info.wake_shield_facility.1', "Power wafers take half the source and time. A triple-junction wafer can be cut into four solar cells. It takes an optional parallel hatch.")
    add('emi.grindless.info.wake_shield_facility.2', "Any orbit. A one-block-thick 9x9 octagonal Whipple disc shelters a 3x3x3 PTFE epitaxy carousel in its wake.")
    add('emi.grindless.info.wake_shield_facility.3', "Circuits 1/2/3: UHPIC wafer / HPIC wafer / triple-junction wafer. Half the source and time for power wafers; cut a triple-junction wafer into four solar cells.")
    add('emi.grindless.info.wake_shield_facility.4', "1-2 energy hatches, 1-2 input buses, 1-2 output buses, 1-2 fluid inputs; optional parallel hatch. All recipes require a cleanroom: fit the maintenance cell with a cleaning maintenance hatch.")
})

ClientEvents.lang('es_es', event => {
    var add = function (key, value) { event.add('grindless', key, value) }

    add('emi.grindless.info.harpoon_anchor_drill.0', "La perforadora anclada con arpones es la perforadora de vetas del cinturón de asteroides. Pon la muestra de veta tipo M, S o C y una broca HSS-S en el bus de entrada; da 11,25 menas en bruto por ciclo y desgasta la broca y un arpón de anclaje.")
    add('emi.grindless.info.harpoon_anchor_drill.1', "Solo funciona en el cinturón y solo hace sus propias recetas. Sin fluido: es vacío. Hasta 256 ciclos a la vez, según permitan las escotillas de energía.")
    add('emi.grindless.info.harpoon_anchor_drill.2', "Familia de perforadoras de vetas, paso 7a: solo en el cinturón de asteroides. Una perforadora se empuja a sí misma lejos de la roca donde casi no hay gravedad, así que unos arpones la sujetan. Solo hace sus propias recetas: las vetas de tipo M, S y C del cinturón.")
    add('emi.grindless.info.harpoon_anchor_drill.3', "11,25 menas en bruto y una toba por ciclo. Desgaste: la broca de HSS-S al 0,25 % por ciclo y un arpón de anclaje al 1 %. Sin fluido: es el vacío. Hasta 256 ciclos a la vez, según permitan las escotillas de energía.")
    add('emi.grindless.info.harpoon_anchor_drill.4', "Una araña de 7x8x7: una base de 5x6 de carcasa de regolito asteroidal, cuatro patas-arpón de HSS-S, un cuerpo de 3x3x3 con un escudo Whipple detrás y una torre de titanio sobre una sarta de tubería de acero de tungsteno. Cuerpo: 1-2 escotillas de energía, 1-2 buses de entrada, 1-2 buses de salida.")

    add('emi.grindless.info.asteroid_processor.0', "El procesador de asteroides ejecuta el proceso Mond. Circuito 1: hierro meteórico triturado. Circuito 3: polvo de hierro meteórico. Ambos dan hierro, níquel y cobalto y dejan el concentrado de PGM de asteroide. Circuito 2: separa la tetrataenita triturada de su kamacita.")
    add('emi.grindless.info.asteroid_processor.1', "Los circuitos 1 y 3 necesitan una carga de 1000 mB de monóxido de carbono en una escotilla de entrada, que no se gasta. Conserva el concentrado y se niega a eliminar objetos. Funciona en cualquier sitio.")
    add('emi.grindless.info.asteroid_processor.2', "El proceso Mond: el metal y el monóxido de carbono forman carbonilos gaseosos que se destilan por separado y se descomponen en hierro, níquel y cobalto puros. Los metales del grupo del platino no forman carbonilos y se quedan como concentrado de MGP asteroidal, que solo hace esta máquina.")
    add('emi.grindless.info.asteroid_processor.3', "Circuito 1: 16 de hierro meteórico triturado. Circuito 3: 16 de polvo de hierro meteórico. Ambos necesitan una carga de 1000 mB de monóxido de carbono en una escotilla de entrada, que nunca se gasta, y conservan el concentrado: sin destruir objetos. Circuito 2: la separación magnética de la tetrataenita triturada de su kamacita.")
    add('emi.grindless.info.asteroid_processor.4', "Una columna de carbonilos hueca de 5x5x6 de carcasa de tubería de acero, un separador magnético de 3x3x3 de carcasa de acero y un gasómetro de CO de vidrio laminado. Separador: 1-2 escotillas de energía, buses de entrada/salida y escotillas de entrada. Funciona en cualquier sitio.")

    add('emi.grindless.info.optical_miner.0', "El minero óptico solo funciona en el cinturón de asteroides. El circuito 1 embolsa un bloque de tipo C y lo descascara con luz solar: agua, dióxido de carbono, carbono y el extracto condrítico. El circuito 2 convierte dióxido de carbono y carbono en monóxido de carbono.")
    add('emi.grindless.info.optical_miner.1', "El circuito 1 solo arranca de día, con el sol sobre el receptor y los ocho espejos a cielo abierto. El circuito 2 no necesita sol. Lo conserva todo y se niega a eliminar. El monóxido de carbono alimenta el procesador de asteroides.")
    add('emi.grindless.info.optical_miner.2', "Solo en el cinturón de asteroides. El circuito 1 embolsa una roca de tipo C y la desconcha con luz solar concentrada: agua, dióxido de carbono, carbono y el extracto condrítico, que solo hace esta máquina. Una bolsa de captura se gasta al 5 % por ciclo.")
    add('emi.grindless.info.optical_miner.3', "Un ciclo del circuito 1 solo empieza de día, con el sol en la ventana receptora y los ocho espejos bajo el cielo abierto. El circuito 2 (Boudouard) convierte el dióxido de carbono y el carbono en el monóxido de carbono del procesador de asteroides, con o sin sol. Conserva todo lo que produce: sin destruir nada.")
    add('emi.grindless.info.optical_miner.4', "Ocho espejos heliostato (vidrio laminado sobre postes de titanio) alrededor de una cámara de captura robusta de 3x3x3 con una ventana receptora de vidrio laminado, una trampa fría resistente a la helada y una caseta de 3x3x3 de carcasa de regolito asteroidal. Caseta: 1-2 escotillas de energía, 1 bus de entrada, buses de salida, hasta 1 escotilla de entrada y 1-3 escotillas de salida.")

    add('emi.grindless.info.biofoundry.0', "La biofundición es la cadena estéril de GregTech en una sola nave, sin sala limpia estéril. Circuitos 1-2: colágeno. 3: gelatina. 4: agar. 5: lodo bacteriano. 6: mutágeno. 7: medio de cultivo estéril. 8: células madre.")
    add('emi.grindless.info.biofoundry.1', "Todo entra y sale por el muro trasero. Se niega a eliminar: el lodo, el ácido y el fósforo vuelven a la cadena. Sus productos alimentan el laboratorio de organoides.")
    add('emi.grindless.info.biofoundry.2', "Una nave estéril y estanca: plascreto y vidrio de sala limpia, cuatro columnas de fermentación, una bahía de autoclaves, un techo de lámparas UV y una esclusa con puertas de hierro. Todo entra y sale por el muro trasero. El circuito programado elige el paso.")
    add('emi.grindless.info.biofoundry.3', "Toda la cadena estéril de GregTech en LuV, sin sala limpia estéril: 1-2 colágeno (de hueso o de harina de hueso), 3 gelatina, 4 agar, 5 lodo bacteriano, 6 mutágeno, 7 medio de cultivo estéril, 8 células madre. Las mismas proporciones y la misma energía que los pasos de GregTech; los pasos fusionados guardan dentro sus intermedios.")
    add('emi.grindless.info.biofoundry.4', "9 y 10: semillas de cebada y de tabaco modificadas para el anillo hidropónico giratorio, con las bacterias como vector que lleva el gen. Las bacterias vienen del cultivo de Europa.")
    add('emi.grindless.info.biofoundry.5', "Guarda todo lo que hace: el lodo de las células madre vuelve a mutágeno, el ácido diluido y el fósforo vuelven a ácido, y no acepta tirar nada. Muro trasero: 1-2 escotillas de energía, 1-4 buses de entrada, 1-2 buses de salida, 1-3 escotillas de entrada y 1-2 escotillas de salida. Valen las piezas ME.")

    add('emi.grindless.info.coated_conductor_line.0', "La línea de conductor recubierto fabrica cinta superconductora de segunda generación. Circuito 1: cinta de níquel-wolframio con polvo de níquel y de wolframio. Circuito 2: conductor recubierto de ITBTC con esa cinta, polvo de ITBTC, oxígeno y plata fundida.")
    add('emi.grindless.info.coated_conductor_line.1', "No necesita alto horno de 6000 K ni helio líquido. El conductor recubierto va a la fábrica de imanes HTS.")
    add('emi.grindless.info.coated_conductor_line.2', "Una línea de bobina a bobina para cinta superconductora de segunda generación: bobina de salida, tren de laminación, horno de recocido, cámara de depósito por láser, tubo de recocido en oxígeno, celda de pulverización de plata y bobina de recogida. El circuito programado elige el paso: 1 sustrato, 2 cinta.")
    add('emi.grindless.info.coated_conductor_line.3', "Sustrato: 19 de polvo de níquel y 1 de polvo de wolframio dan 20 de cinta de níquel-wolframio. Cinta: 16 de ella, 1 de polvo de ITBTC, 1000 mB de oxígeno y 36 mB de plata fundida dan 16 de conductor recubierto de ITBTC, sin alto horno de 6000 K ni helio líquido.")
    add('emi.grindless.info.coated_conductor_line.4', "Las filas delantera y trasera de la bancada admiten 1-2 escotillas de energía, 1-3 buses de entrada, 1-2 escotillas de entrada y 1-2 buses de salida; valen las piezas ME. El conductor recubierto alimenta el taller de imanes HTS.")

    add('emi.grindless.info.algae_bioreactor.0', "El biorreactor de algas cultiva materia viva. Circuito 1, en cualquier sitio: las algas convierten agua y CO2 en biomasa y oxígeno. Circuito 2, solo en Europa: salmuera europana, peróxido de hidrógeno, hidrógeno y extracto condrítico dan bacterias, sembradas con la muestra del océano.")
    add('emi.grindless.info.algae_bioreactor.1', "La muestra del océano se conserva. Es la única fuente de bacterias del pack y se niega a eliminar.")
    add('emi.grindless.info.algae_bioreactor.2', "Familia de invernaderos, paso 5. Circuito 1, en cualquier sitio: algas bajo lámparas LED convierten agua y CO2 en biomasa y oxígeno. Circuito 2, solo en Europa: salmuera, peróxido de hidrógeno, hidrógeno y el extracto condrítico del cinturón alimentan el cultivo europano, sembrado con la muestra del océano (se conserva): las únicas bacterias.")
    add('emi.grindless.info.algae_bioreactor.3', "Tres tubos de 1x1x10 de vidrio laminado con lámparas GT entre ellos, sobre una base sellada de 5x5x3 de hormigón de azufre con techo de bóveda antirradiación. Base: 1-2 escotillas de energía, buses de entrada, 1-3 escotillas de entrada y 1-2 de salida.")
    add('emi.grindless.info.algae_bioreactor.4', "Las bacterias van a casa, a la biofactoría. Conserva todo lo que produce: sin descarte.")

    add('emi.grindless.info.cryobot.0', "El criobot es la perforadora de vetas de Europa. Circuito 1: una sonda criobot se funde hasta el océano y trae la muestra del océano y 1000 mB de salmuera. Circuito 2: 8000 mB de salmuera europana y 2000 mB de agua por ciclo.")
    add('emi.grindless.info.cryobot.1', "Solo funciona en Europa y solo hace sus propias recetas. La cabeza de fusión se gasta un 0,25 % por ciclo y la pastilla de RTG dura más o menos una hora. Se niega a eliminar.")
    add('emi.grindless.info.cryobot.2', "Familia de taladros de vetas, paso 7b. Solo en Europa. Circuito 1: una sonda criobot se funde hasta el océano y trae la muestra del océano de Europa y 1000 mB de salmuera. Circuito 2: 8000 mB de salmuera europana y 2000 mB de agua de fusión por ciclo.")
    add('emi.grindless.info.cryobot.3', "La cabeza de fusión se gasta un 0,25% por ciclo de salmuera y su pastilla de RTG se consume más o menos una vez por hora. Solo hace sus propias recetas. Conserva la muestra y la salmuera: sin descarte.")
    add('emi.grindless.info.cryobot.4', "Base de 5x5 de hormigón de azufre alrededor de un núcleo de bóveda antirradiación, una torre de 3x3x10 de acero de tungsteno bajo una cabeza de bóveda con un tambor de caja de engranajes de acero de tungsteno, y un pozo de 1x5 de hielo compacto o azul bajo el centro de la base. Base: 1-2 escotillas de energía, buses de entrada y salida, 1-2 escotillas de salida.")

    add('emi.grindless.info.gravitational_wave_detector.0', "El detector de ondas gravitacionales solo funciona en Ganímedes. Circuito 1: un orbe de datos, 100 mB de helio líquido y la señal de Sagitario A* (se conserva) dan un catálogo de ondas gravitacionales tras 12 000 ticks.")
    add('emi.grindless.info.gravitational_wave_detector.1', "Mantén cargada toda la L mientras escucha. Conserva sus catálogos y se niega a eliminar objetos.")
    add('emi.grindless.info.gravitational_wave_detector.2', "Solo en Ganímedes: hielo tranquilo, 110 K y su propia magnetosfera. Circuito 1: un orbe de datos, 100 mB de helio líquido y la señal de Sagitario A* (se conserva) dan un catálogo de ondas gravitacionales tras una campaña de 12 000 ticks. Mantén toda la L cargada mientras escucha.")
    add('emi.grindless.info.gravitational_wave_detector.3', "Una L enterrada de 33x5x33: un vértice de 5x5x5 a prueba de escarcha (controlador, escotillas, mantenimiento), dos tubos huecos de 3x3 de acero inoxidable limpio de 25 de largo, una estación final de 3x3x3 a prueba de escarcha en cada brazo, cuatro masas de prueba de zafiro (dos en las paredes del vértice y una mirando al vértice en cada extremo) y hielo compacto o azul sobre cada tubo y estación final. Conserva sus catálogos: sin descarte.")

    add('emi.grindless.info.coilgun_launcher.0', "El lanzador de sondas por bobinas solo funciona en Ganímedes. El circuito 1 dispara una sonda de entrada en Júpiter para el estudio atmosférico joviano. El circuito 2 envía una sonda de sobrevuelo de Saturno con asistencia de Júpiter para la carta de transferencia a Saturno.")
    add('emi.grindless.info.coilgun_launcher.1', "Sin aire y a 110 K: las bobinas superconducen sin criostato. Conserva los datos de las sondas y se niega a eliminar objetos.")
    add('emi.grindless.info.coilgun_launcher.2', "Solo en Ganímedes: sin aire, y a 110 K las bobinas de Hg-1223 superconducen sin criostato. El circuito 1 dispara una sonda de entrada en Júpiter para el estudio atmosférico joviano; el circuito 2 envía una sonda de sobrevuelo de Saturno con asistencia gravitatoria de Júpiter para la carta de transferencia a Saturno.")
    add('emi.grindless.info.coilgun_launcher.3', "37x5x8: un cañón de 33 anillos de ocho carcasas de bobina alrededor de un ánima abierta, una recámara de 5x5x4 de acero de tungsteno robusto (controlador en la cara trasera, bus de carga, escotillas, mantenimiento) y un banco de pulsos de 3x3x3 de acero de tungsteno al lado. Conserva sus datos: sin descarte.")

    add('emi.grindless.info.helium_refrigerator.0', "El refrigerador de helio es un enfriador de helio en circuito cerrado. Hace el trabajo del congelador al vacío con lingotes calientes y con metal fundido en un molde de lingote, pero gasta 25 mB de helio líquido por receta en vez de 250 mB.")
    add('emi.grindless.info.helium_refrigerator.1', "Paga la diferencia en EU para volver a licuar el helio. 50 mB de nitrógeno líquido preenfrían el circuito y salen como nitrógeno gaseoso.")
    add('emi.grindless.info.helium_refrigerator.2', "Un refrigerador de helio de ciclo Claude: una caja fría con dos turboexpansores, una sala de compresores y un gasómetro de helio. Enfría cada lingote caliente, y cada metal fundido en un molde de lingote, que el congelador al vacío enfría con helio líquido.")
    add('emi.grindless.info.helium_refrigerator.3', "El helio circula en un circuito cerrado: cada receta gasta 25 mB de helio líquido en vez de los 250 mB del congelador, y paga en EU volver a licuar el resto. 50 mB de nitrógeno líquido preenfrían el circuito y salen como nitrógeno gaseoso.")
    add('emi.grindless.info.helium_refrigerator.4', "Necesita una carga de 4000 mB de helio líquido en sus escotillas de entrada, además de la reposición. La carga nunca se gasta; con una escotilla de paralelo sigue siendo de 4000 mB, más 25 mB por cada copia.")
    add('emi.grindless.info.helium_refrigerator.5', "El anillo del suelo de la caja fría admite 1-2 escotillas de energía, 1-2 buses de entrada, 1-2 buses de salida, 1-4 escotillas de entrada y 1-2 escotillas de salida; valen las piezas ME. El nitrógeno vuelve a la planta criogénica, o se tira.")

    add('emi.grindless.info.hts_magnet_works.0', "La fábrica de imanes HTS hace imanes con cinta superconductora. Circuito 1: bobina HTS (bloque de bobina superconductora). 2: celda SMES LuV. 3: carcasas de bobina de cañón de bobinas. 4: cojinete magnético.")
    add('emi.grindless.info.hts_magnet_works.1', "La bobina HTS lleva conductor recubierto de ITBTC, láminas de niobio-titanio, trinio y epoxi, con mucho menos trinio que la receta LuV de GTM. La celda SMES es la celda LuV de la red inalámbrica.")
    add('emi.grindless.info.hts_magnet_works.2', "Una fábrica de imanes: la cinta superconductora se bobina en un mandril giratorio, se impregna de epoxi en un tanque de vacío y se prueba en frío en un criostato de helio líquido. El circuito programado elige el producto: 1 bobina HTS, 2 celda SMES LuV, 3 carcasas de bobina de cañón de bobinas, 4 cojinete magnético.")
    add('emi.grindless.info.hts_magnet_works.3', "Bobina HTS: 16 de conductor recubierto de ITBTC, 16 láminas de niobio-titanio, 144 mB de trinio y 144 mB de epoxi dan el bloque de bobina superconductora de GTM con una vigésima cuarta parte del trinio que pide su receta LuV. Celda SMES: la celda LuV de la red inalámbrica, 983 040 000 EU en el campo de una bobina.")
    add('emi.grindless.info.hts_magnet_works.4', "Cada bobinado necesita una carga de 1000 mB de helio líquido en una escotilla de entrada para su prueba en frío: nunca se gasta. No sobra nada.")
    add('emi.grindless.info.hts_magnet_works.5', "Las filas delantera y trasera de la base y la pared delantera del criostato admiten 1-2 escotillas de energía, 1-3 buses de entrada, 1-3 escotillas de entrada y 1-2 buses de salida; valen las piezas ME. Dos escotillas de energía del mismo nivel suben el voltaje un nivel, también las inalámbricas.")

    add('emi.grindless.info.flux_tube_tether.0', "El cable del tubo de flujo es una central solo en la órbita de Ío. Un cable desnudo barre el toro de plasma de Ío y no quema nada. Cada ciclo de 20 s necesita el circuito 1, 50 mB de argón y dos carretes de cable en el bus.")
    add('emi.grindless.info.flux_tube_tether.1', "Da 65 536 EU/t por celda de carrete: 131 072 EU/t con las dos. Un carrete se gasta más o menos una vez por hora.")
    add('emi.grindless.info.flux_tube_tether.2', "El giro de Júpiter como energía: un cable desnudo desplegado desde una estación en el toro de plasma de Ío, que lo barre a unos 57 km/s y hace pasar una corriente por él. No quema nada. Solo en la órbita de Ío.")
    add('emi.grindless.info.flux_tube_tether.3', "Cada ciclo de 20 s necesita el circuito 1, 50 mB de argón (el cátodo hueco, 25 mB por carrete) y dos carretes de cable en el bus, y da 65 536 EU/t por celda de carrete: 131 072 EU/t con las dos. Un carrete se gasta más o menos una vez por hora.")
    add('emi.grindless.info.flux_tube_tether.4', "Su energía sale por 1-4 escotillas dínamo, o por una escotilla dínamo inalámbrica LuV hacia la red; los dos carretes necesitan sitio para 131 072 EU/t (una escotilla LuV de 4 A).")
    add('emi.grindless.info.flux_tube_tether.5', "5x15x5: un desplegador de 5x5x5 con aristas de carcasa de armazón de estación y caras de carcasa de bóveda antirradiación (1-4 escotillas dínamo, 1 bus de entrada), dos carretes de tres cajas de engranajes de acero de tungsteno dentro, una escotilla de entrada (el puerto del cátodo hueco) en el techo junto al cable, y un cable de marcos de aluminio desde el centro del techo 10 bloques hacia arriba.")

    add('emi.grindless.info.fumarole_condenser.0', "El condensador de fumarolas trabaja los gases volcánicos de Ío. Circuito 1, solo en Ío: SO2, azufre y un sublimado jónico. Circuito 2, en cualquier sitio: sublimados, hidrógeno y una carga de HCl dan germanio e indio. Circuito 3, solo en Ío: hormigón de azufre.")
    add('emi.grindless.info.fumarole_condenser.1', "La carga de HCl se conserva. Se niega a eliminar. Es la única fuente de germanio antes de ZPM.")
    add('emi.grindless.info.fumarole_condenser.2', "Los gases volcánicos de Ío, enfriados por bandas: el único germanio antes de ZPM, el indio de Ío y el hormigón de azufre. Su carcasa es de bóveda antirradiación.")
    add('emi.grindless.info.fumarole_condenser.3', "Circuito 1, solo en Ío: recoge 4000 mB de SO2, 8 de azufre y un sublimado jónico. Circuito 2, en cualquier sitio: 4 sublimados + 2000 mB de hidrógeno sobre una carga de 1000 mB de HCl (se conserva) -> 2 de germanio, 1 de indio y agua. Circuito 3, solo en Ío: 8 de azufre + 8 de basalto o arena negra -> 8 de hormigón de azufre.")
    add('emi.grindless.info.fumarole_condenser.4', "Guarda todo lo que produce: no funciona si está puesto a tirar. Admite la escotilla de paralelismo. Funciona con una escotilla de energía inalámbrica IV traída.")
    add('emi.grindless.info.fumarole_condenser.5', "5x15x5: tres fumarolas de azufre de Biomes O' Plenty en el suelo bajo la columna; un recinto de bóveda de 5x5x2 (1-2 escotillas de energía, 1-2 buses de entrada y de salida, 1-3 escotillas de entrada, 1-2 de salida, escotilla de paralelismo opcional); una columna de 3x3 con cuatro zonas de 3 bloques: acero de tungsteno robusto, acero inoxidable limpio, marcos de aluminio y carcasa a prueba de heladas.")

    add('emi.grindless.info.volcanic_intake.0', "La toma volcánica es una central solo en Ío. No quema nada: un ciclo de dióxido de azufre corre entre el magma de la pátera y el cielo frío de Ío. Cada ciclo de 20 s necesita el circuito 1 y una carga de 4000 mB de SO2, que se conserva.")
    add('emi.grindless.info.volcanic_intake.1', "Da 32 768 EU/t por módulo de turbina completo, hasta 131 072 EU/t. Un haz intercambiador de calor por módulo se gasta más o menos una vez por hora.")
    add('emi.grindless.info.volcanic_intake.2', "El calor de marea de Ío como energía: un ciclo Rankine cerrado de dióxido de azufre entre el magma de la pátera y el cielo de 110 K de Ío. No quema nada. Solo en Ío.")
    add('emi.grindless.info.volcanic_intake.3', "Cada ciclo de 20 s necesita el circuito 1 y una carga de 4000 mB de SO2 (se conserva) y da 32 768 EU/t por módulo de turbina completo, hasta 131 072 EU/t. Un haz intercambiador de calor por módulo se gasta más o menos una vez por hora.")
    add('emi.grindless.info.volcanic_intake.4', "Su energía sale por 1-4 escotillas dínamo, o por una escotilla dínamo inalámbrica LuV hacia la red. Hasta 3 módulos de turbina más: cada hueco es un módulo entero de 3x3x3 de carcasa de turbina de titanio, o aire.")
    add('emi.grindless.info.volcanic_intake.5', "11x12x5: una zapata de 5x5 de hormigón de azufre con 3x3 bloques de magma bajo una placa caliente de hogares de acero de tungsteno; una sala de bóveda (1 bus de entrada, 1 escotilla de entrada, escotillas dínamo) y una torre de 5x5x10 de hormigón de azufre alrededor de un tubo de acero de tungsteno; aletas de radiadores de cielo nocturno arriba; módulos de turbina a ambos lados.")

    add('emi.grindless.info.mega_chemical_complex.0', "El complejo químico mega tiene dos modos que se eligen en el controlador: todas las recetas del reactor químico y del reactor químico grande, o las líneas largas de PTFE, epoxi y para-aramida en un solo paso con cada subproducto como salida.")
    add('emi.grindless.info.mega_chemical_complex.1', "El paralelo es 2^(temperatura de bobina / 900 K) por la escotilla de paralelos. Cada copia paga su EU/t completo, así que las escotillas de energía fijan cuántas corren. Las bobinas por encima de cuproníquel recortan la energía un 5 %, hasta el 80 %.")
    add('emi.grindless.info.mega_chemical_complex.2', "El reactor químico grande masivo, con dos modos que se eligen en el controlador: todas las recetas del reactor químico grande y del reactor químico, o sus propias líneas químicas largas (PTFE, epoxi, para-aramida) hechas en un solo paso a partir de las recetas reales: las mismas entradas, cada subproducto como salida y la energía de todas las etapas sumada.")
    add('emi.grindless.info.mega_chemical_complex.3', "Copias a la vez: 2^(temperatura de la bobina / 900 K) por la escotilla de paralelos, sin tope (bobina HSS-G 64 x escotilla LuV 16 = 1024; bobina de Naquadah 256 x escotilla ZPM 64 = 16384). Cada copia paga su EU/t completo, así que las escotillas de energía fijan cuántas corren: floor(voltaje de la escotilla / EU/t de la receta).")
    add('emi.grindless.info.mega_chemical_complex.4', "Cada nivel de bobina sobre el Cuproníquel recorta la energía un 5% (hasta el 80%), el voltaje sobrante da sobrecargas perfectas y el modo por lotes está activo.")
    add('emi.grindless.info.mega_chemical_complex.5', "Necesita, en una carcasa de 15 x 15 x 15 de carcasas inertes de PTFE con marcos de HSS-S en las aristas: 4 anillos de 32 bobinas calefactoras del mismo tipo, una columna de carcasas de tubería de PTFE, vidrio laminado en las paredes laterales; en cualquier celda de carcasa 1 escotilla de mantenimiento, 1 o 2 escotillas de energía, 1 escotilla de paralelos, hasta 2 buses de entrada y 2 de salida, hasta 8 escotillas de entrada de fluidos y 6 de salida.")

    add('emi.grindless.info.hydroponic_ring.0', "El anillo hidropónico giratorio es cultivo molecular solo en órbita, no un multiplicador de cosechas. Circuito 5: semilla de cebada (se conserva), agua y CO2 dan factor neurotrófico. Circuito 6: semilla de tabaco (se conserva) da colágeno vegetal. Ambos dan también biomasa y oxígeno.")
    add('emi.grindless.info.hydroponic_ring.1', "La biomasa alimenta la biofundición y el factor neurotrófico, el laboratorio de organoides. El oxígeno sostiene la estación. Se niega a eliminar.")
    add('emi.grindless.info.hydroponic_ring.2', "Agricultura molecular solo en órbita, no un multiplicador de cultivos. Circuito 5: semilla de cebada conservada, agua y CO2 para factor neurotrófico. Circuito 6: semilla de tabaco conservada para colágeno vegetal. Ambos producen biomasa y oxígeno.")
    add('emi.grindless.info.hydroponic_ring.3', "Lecho anular de tierra de 15x15x3 bajo vidrio templado; radios de titanio hasta un núcleo de 3x3x3 con cuatro cojinetes magnéticos. Controlador de atraque en el borde cercano. Núcleo: 1-2 escotillas de energía, buses de entrada/salida, 1-2 escotillas de entrada y 2 de salida. Biomasa para la biofactoría y oxígeno para la estación. Sin modo de cultivos ordinarios ni descarte.")

    add('emi.grindless.info.organoid_lab.0', "El laboratorio de organoides funciona solo en órbita, con sala limpia o una escotilla de mantenimiento con limpieza. El circuito 1 cultiva un organoide neuronal con células madre, medio estéril y factor neurotrófico. El circuito 2 monta una unidad de procesamiento neuronal.")
    add('emi.grindless.info.organoid_lab.1', "La unidad de procesamiento gasta 30 720 EU/t durante 1563 ticks. Las células madre vienen de la biofundición y el factor neurotrófico, del anillo hidropónico. Conserva todo y se niega a eliminar.")
    add('emi.grindless.info.organoid_lab.2', "Solo en órbita, con sala limpia o escotilla de mantenimiento con limpieza. Circuito 1: células madre, medio estéril y factor neurotrófico del anillo para un organoide neuronal. Circuito 2: unidad de procesamiento neuronal a 30 720 EU/t durante 1563 ticks.")
    add('emi.grindless.info.organoid_lab.3', "Módulo sellado de 5x5x5 de plascreta y vidrio de sala limpia, incubadora laminada, cuatro filtros y celda de mantenimiento, unido a la estructura de estación. 1-2 escotillas de energía, buses de entrada/salida y escotillas de entrada. Conserva todos los productos: sin descarte.")

    add('emi.grindless.info.zero_g_crystal_grower.0', "El cultivador de cristales en gravedad cero funciona solo en órbita, con sala limpia o una escotilla de mantenimiento con limpieza. Los circuitos 1-5 cultivan chips de cristal en bruto con 100 % de certeza en 3000 ticks, con las dosis de dopante de GregTech. El circuito 6 cultiva una masa de prueba de zafiro.")
    add('emi.grindless.info.zero_g_crystal_grower.1', "La masa de prueba de zafiro es una pieza del detector de ondas gravitacionales.")
    add('emi.grindless.info.zero_g_crystal_grower.2', "Solo en órbita. Los circuitos 1-5 producen chips de cristal en bruto con certeza del 100% en 3000 ticks, con las dosis originales de dopante de GregTech. El circuito 6 produce una masa de prueba de zafiro.")
    add('emi.grindless.info.zero_g_crystal_grower.3', "Módulo de estación de 5x5x5; núcleo inerte de 3x3x3 y ventanas laminadas. Requiere sala limpia o escotilla de mantenimiento con limpieza. 1-2 escotillas de energía, buses de entrada/salida y escotillas de entrada.")

    add('emi.grindless.info.microgravity_smelter.0', "La fundición de microgravedad funciona en cualquier órbita. Circuito 1: tubos ópticos de ZBLAN. Circuito 2: espuma de escudo Whipple. Circuito 3: aleación de naquadah fría sin helio.")
    add('emi.grindless.info.microgravity_smelter.1', "Mezcla el ZBLAN en el recipiente de mezcla grande. Los tubos ópticos no se pueden reciclar y piden una escotilla de mantenimiento con limpieza. Admite una escotilla de paralelos opcional.")
    add('emi.grindless.info.microgravity_smelter.2', "Cualquier órbita. Módulo orbital de 3x3x7, ocho bobinas de HSS-G alrededor de un centro de levitación vacío y una torre de estirado de fibra de seis bloques.")
    add('emi.grindless.info.microgravity_smelter.3', "Circuitos 1/2/3: tubos ópticos de ZBLAN / espuma para escudo Whipple / aleación fría de naquadah sin helio. Mezcla ZBLAN en la gran mezcladora (73.250 mB de flúor por 25 polvos). Los tubos ópticos no se pueden reciclar.")
    add('emi.grindless.info.microgravity_smelter.4', "1-2 escotillas de energía, 1-2 buses de entrada, 1-2 de salida y 1-2 entradas de fluidos; escotilla de paralelismo opcional. Un hueco de mantenimiento: usa una escotilla de mantenimiento con limpieza para los tubos ópticos.")

    add('emi.grindless.info.wake_shield_facility.0', "La instalación de escudo de estela funciona en cualquier órbita y siempre pide sala limpia o una escotilla de mantenimiento con limpieza. Circuito 1: oblea UHPIC. Circuito 2: oblea HPIC. Circuito 3: oblea de triple unión.")
    add('emi.grindless.info.wake_shield_facility.1', "Las obleas de potencia llevan la mitad de fuente y de tiempo. Una oblea de triple unión se puede cortar en cuatro células solares. Admite una escotilla de paralelos opcional.")
    add('emi.grindless.info.wake_shield_facility.2', "Cualquier órbita. Disco octogonal de Whipple de 9x9 y un bloque de grosor; protege un carrusel de epitaxia de PTFE de 3x3x3 en su estela.")
    add('emi.grindless.info.wake_shield_facility.3', "Circuitos 1/2/3: oblea UHPIC / oblea HPIC / oblea de triple unión. Mitad de material y tiempo para las obleas de potencia; corta una oblea de triple unión en cuatro células solares.")
    add('emi.grindless.info.wake_shield_facility.4', "1-2 escotillas de energía, 1-2 buses de entrada, 1-2 de salida y 1-2 entradas de fluidos; escotilla de paralelismo opcional. Todas las recetas requieren sala limpia: coloca una escotilla de mantenimiento con limpieza.")
})
